    nlohmann::json jneg = neg::a;
    assert(jneg.is_number_integer() && jneg == -5);
    assert(jneg.get<neg>() == neg::a);

    nlohmann::json ja = anon;
    assert(ja == 102);
    assert(ja.get<decltype(anon)>() == anon);

    nlohmann::json jbig = static_cast<book_id>(0xFFFFFFFFFFFFFFFFULL);
    assert(jbig.is_number_unsigned() && nlohmann::to_string(jbig) == "18446744073709551615");

    std::cout << "all repro checks passed\n";
}
